		if v := strings.TrimSpace(os.Getenv(name)); v != "" {
			username = v
			break
		}
	}
	if username == "" {
		for _, name := range []string{"SPACE_TRACK_IDENTITY", "SPACE_TRACK_USERNAME", "ST_USER", "st-user"} {
			if v := strings.TrimSpace(dotEnvValues[name]); v != "" {
