func (a *App) loadSpaceTrackSatcatDetails(ctx context.Context, catnr int) map[string]any {
	now := float64(time.Now().Unix())
	if cached, ok := a.spaceTrack.get(catnr, now, satcatCacheTTL, satcatFailTTL); ok {
		return cached
	}
