func TestSessionCookiePathReachesGuardedRoutes(t *testing.T) {
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		_, _ = w.Write([]byte(`{"success": true}`))
	}))
	t.Cleanup(srv.Close)
	overrideURL(t, &turnstileVerifyURL, srv.URL+"/siteverify")

	a := newTurnstileTestApp(t, "test-site", "test-secret")
	stubSearchURLs(t)
	r := a.router()

	jar, _ := cookiejar.New(nil)
	client := &http.Client{Jar: jar}

	// 1. handshake
	u, _ := url.Parse("https://app.example.com/api/turnstile/session")
	req, _ := http.NewRequest("GET", u.String(), nil)
	req.Header.Set("X-Turnstile-Token", "raw-token")
	resp, err := client.Do(req)
	if err != nil {
		t.Fatal(err)
	}
	resp.Body.Close()
	if resp.StatusCode != 200 {
		t.Fatalf("handshake status = %d", resp.StatusCode)
	}
	var setCookie string
	for _, h := range resp.Header.Values("Set-Cookie") {
		if strings.Contains(h, turnstileCookieName+"=") {
			setCookie = h
		}
	}
	t.Logf("Set-Cookie: %s", setCookie)

	// 2. guarded route with same jar (real browser cookie-path semantics)
	u2, _ := url.Parse("https://app.example.com/api/search?q=London")
	resp2, err := client.Get(u2.String())
	if err != nil {
		t.Fatal(err)
	}
	resp2.Body.Close()
	t.Logf("guarded /api/search status = %d", resp2.StatusCode)
	if resp2.StatusCode != 200 {
		t.Errorf("cookie not honored on /api/search: status = %d (cookie Path missing?)", resp2.StatusCode)
	}
	_ = atomic.Int64{}
}
EOF
