	if resp3.StatusCode != 200 {
		t.Errorf("cookie not honored on /api/search: status = %d (cookie Path missing?)", resp3.StatusCode)
	}
}

func mustReq(target string, hdr map[string]string) *http.Request {
	r, _ := http.NewRequest("GET", target, nil)
	for k, v := range hdr {
		r.Header.Set(k, v)
	}
	return r
}
